sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event, helpers, imports}) {
    const {columnId,taskId} = event.payload.selectedCell;
    const {
        gantt_data,
        column_conf
    } = api.data.project_task_chronology_1.output.result;
    const selected_task = gantt_data.find(t => t.id === taskId);
    const cellConf = column_conf.find(c => c.name === columnId);
    const table = selected_task.u_table_name.value;
    if(!cellConf.internalColumnName[table]){
        api.emit("NOW_UXF_PAGE#ADD_NOTIFICATIONS", {
        items: [{
            id: "cellEditValidation",
            status: "critical",
            icon: "ban-fill",
            content: {
                type: "html",
                value: "<h4>" + "Edit of this field is not allowed for the selected record." + "<h4>"
            },
            action: {
                type: "dismiss"
            },
        }]
    });
    }

}
